using Domain.Grammar;

namespace Infrastructure.Persistence.Seeding.German;

internal static class GrammarSeedData
{
    private const long SeedBase = FoundationSeedData.GermanId;
    private static readonly (int Key, string Code, string NativeName, string Pattern, string VietnameseName,
        string EnglishName, string VietnameseExplanation, string EnglishExplanation, string VietnameseNote,
        string EnglishNote)[] Points =
    [
        (0, "statement-v2", "Verbzweitstellung", "Vorfeld + finites Verb + weitere Satzteile", "Động từ ở vị trí thứ hai", "Verb-second statements", "Trong câu trần thuật chính, động từ đã chia đứng ở vị trí thành phần thứ hai. Heute lerne ich Deutsch. nghĩa là Hôm nay tôi học tiếng Đức.", "In a main declarative clause, the finite verb occupies the second constituent position. Heute lerne ich Deutsch. means Today I am learning German.", "Vị trí thứ hai tính theo thành phần câu, có thể gồm nhiều từ.", "The second position counts constituents, which may contain several words."),
        (1, "yes-no-questions", "Ja-Nein-Fragen", "Finites Verb + Subjekt + weitere Satzteile?", "Câu hỏi có hoặc không", "Yes-no questions", "Đặt động từ đã chia trước chủ ngữ. Lernen Sie Deutsch? nghĩa là Ông/bà có học tiếng Đức không?", "Place the finite verb before the subject. Lernen Sie Deutsch? means Are you learning German, in formal address.", "Kết thúc câu hỏi viết bằng dấu hỏi.", "Use a question mark in writing."),
        (2, "w-questions", "W-Fragen", "Fragewort + finites Verb + Subjekt + ...?", "Câu hỏi với từ để hỏi", "Questions with question words", "Đặt từ để hỏi ở đầu, theo sau là động từ đã chia. Wo wohnen Sie? nghĩa là Ông/bà sống ở đâu?", "Put the question word first, followed by the finite verb. Wo wohnen Sie? means Where do you live, in formal address.", "wer hỏi người, was hỏi sự việc, wo hỏi vị trí, wohin hỏi hướng đến.", "wer asks about people, was about things, wo about location and wohin about destination."),
        (3, "personal-pronouns", "Personalpronomen", "ich, du, er, sie, es, wir, ihr, sie, Sie", "Đại từ nhân xưng", "Personal pronouns", "Chọn đại từ theo ngôi, số và quan hệ giao tiếp. Wir lernen. nghĩa là Chúng tôi học.", "Choose the pronoun by person, number and form of address. Wir lernen. means We are learning.", "sie có thể chỉ cô ấy hoặc họ. Sie viết hoa dùng để xưng hô lịch sự.", "sie can mean she or they. Capitalized Sie is formal you."),
        (4, "sein-present", "sein im Präsens", "ich bin, du bist, er/sie/es ist, wir sind, ihr seid, sie/Sie sind", "Động từ sein ở hiện tại", "Present tense of sein", "Dùng sein để giới thiệu hoặc miêu tả trạng thái. Ich bin müde. nghĩa là Tôi mệt.", "Use sein to identify someone or describe a state. Ich bin müde. means I am tired.", "sein chia bất quy tắc, cần học từng dạng.", "sein is irregular, so learn its forms individually."),
        (5, "haben-present", "haben im Präsens", "ich habe, du hast, er/sie/es hat, wir haben, ihr habt, sie/Sie haben", "Động từ haben ở hiện tại", "Present tense of haben", "Dùng haben để nói có hoặc sở hữu. Ich habe ein Buch. nghĩa là Tôi có một quyển sách.", "Use haben to express having or possessing something. Ich habe ein Buch. means I have a book.", "Dạng du và er/sie/es bỏ b của thân động từ.", "The du and er/sie/es forms drop the b from the stem."),
        (6, "regular-present", "Regelmäßige Verben", "Verbstamm + Personalendung", "Động từ thường ở hiện tại", "Regular present-tense verbs", "Bỏ -en của nguyên mẫu rồi thêm đuôi theo chủ ngữ. Với lernen, các dạng là lerne, lernst, lernt, lernen, lernt, lernen.", "Remove -en from the infinitive and add the personal ending. lernen gives lerne, lernst, lernt, lernen, lernt and lernen.", "Các đuôi cơ bản theo ich, du, er/sie/es, wir, ihr, sie/Sie là -e, -st, -t, -en, -t, -en.", "The basic endings for ich, du, er/sie/es, wir, ihr and sie/Sie are -e, -st, -t, -en, -t and -en."),
        (7, "verb-stem-changes", "Stammvokalwechsel", "du / er, sie, es + veränderter Verbstamm", "Biến đổi nguyên âm thân động từ", "Stem-vowel changes", "Một số động từ đổi nguyên âm ở ngôi du và er/sie/es. sprechen có du sprichst và er spricht; fahren có du fährst và sie fährt.", "Some verbs change their stem vowel with du and er/sie/es. sprechen has du sprichst and er spricht; fahren has du fährst and sie fährt.", "Học dạng ngôi ba cùng nguyên mẫu để nhận diện nhóm biến đổi.", "Learn the third-person singular together with the infinitive."),
        (8, "formal-address", "Anrede mit du und Sie", "du / ihr / Sie", "Xưng hô thân mật và lịch sự", "Informal and formal address", "Dùng du với một người trong quan hệ thân mật, ihr với nhiều người thân mật và Sie khi xưng hô lịch sự. Wie heißen Sie? nghĩa là Ông/bà tên gì?", "Use du for one person informally, ihr for several people informally and Sie for formal address. Wie heißen Sie? means What is your name, formally.", "Động từ với Sie có dạng như ngôi ba số nhiều. Viết hoa cả đại từ Sie và dạng sở hữu Ihr khi xưng hô lịch sự.", "Verbs with Sie use the third-person plural form. Capitalize formal Sie and possessive Ihr."),
        (9, "noun-capitals", "Großschreibung von Nomen", "Nomen mit großem Anfangsbuchstaben", "Viết hoa danh từ", "Capitalizing nouns", "Danh từ tiếng Đức bắt đầu bằng chữ hoa. Das ist ein Buch. nghĩa là Đó là một quyển sách.", "German nouns begin with a capital letter. Das ist ein Buch. means That is a book.", "Quy tắc viết hoa danh từ áp dụng cả giữa câu.", "Noun capitalization also applies in the middle of a sentence."),
        (10, "definite-articles", "Bestimmter Artikel im Nominativ", "der / die / das; Plural die", "Mạo từ xác định và giống", "Definite articles and gender", "Học danh từ cùng giống ngữ pháp và mạo từ. der Tisch, die Tür và das Buch lần lượt là cái bàn, cánh cửa và quyển sách.", "Learn a noun together with its grammatical gender and article. Examples are der Tisch, die Tür and das Buch.", "Giống ngữ pháp không luôn suy ra từ giới tính hoặc nghĩa. Số nhiều Nominativ dùng die.", "Grammatical gender cannot always be inferred from meaning or natural gender. Nominative plural uses die."),
        (11, "indefinite-articles", "Unbestimmter Artikel im Nominativ", "ein / eine / ein", "Mạo từ bất định", "Indefinite articles", "Dùng ein với danh từ giống đực hoặc trung ở Nominativ, eine với giống cái. Das ist eine Tasche. nghĩa là Đây là một chiếc túi.", "Use ein with masculine and neuter nominative nouns, and eine with feminine nouns. Das ist eine Tasche. means This is a bag.", "Mạo từ bất định không có dạng số nhiều tương ứng với ein.", "There is no corresponding plural form of the indefinite article ein."),
        (12, "plural-nouns", "Pluralformen", "Nomen + gelernte Pluralform", "Số nhiều danh từ", "Plural nouns", "Tiếng Đức có nhiều cách tạo số nhiều. das Buch thành die Bücher, die Tasche thành die Taschen.", "German has several plural patterns. das Buch becomes die Bücher, and die Tasche becomes die Taschen.", "Học dạng số nhiều cùng mỗi danh từ, tránh áp dụng một đuôi chung cho mọi từ.", "Learn the plural with each noun instead of applying one ending to every word."),
        (13, "negation-kein", "Negation mit kein", "kein / keine + Nomen", "Phủ định danh từ bằng kein", "Negating nouns with kein", "Dùng kein thay cho mạo từ bất định hoặc trước danh từ không có mạo từ để phủ định. Ich habe kein Auto. nghĩa là Tôi không có ô tô.", "Use kein in place of an indefinite article or before a noun without an article to negate it. Ich habe kein Auto. means I do not have a car.", "kein thay đổi đuôi theo giống, số và cách, như keine Zeit và keinen Kaffee.", "kein changes ending by gender, number and case, as in keine Zeit and keinen Kaffee."),
        (14, "negation-nicht", "Negation mit nicht", "nicht + negierter Satzteil", "Phủ định bằng nicht", "Negation with nicht", "Dùng nicht để phủ định tính từ hoặc thành phần khác phù hợp. Das Buch ist nicht teuer. nghĩa là Quyển sách không đắt.", "Use nicht to negate an adjective or another appropriate constituent. Das Buch ist nicht teuer. means The book is not expensive.", "Vị trí nicht thay đổi theo phạm vi phủ định. Trong câu chính, phủ định toàn mệnh đề thường đặt về cuối, trước phần vị ngữ còn lại.", "The position of nicht depends on its scope. Clause negation in a main clause commonly appears late, before remaining predicate material."),
        (15, "possessives", "Possessivartikel", "mein / dein / sein / ihr / unser / euer / Ihr + Nomen", "Từ sở hữu đứng trước danh từ", "Possessive determiners", "Từ sở hữu cho biết vật hoặc người thuộc về ai. Das ist meine Tasche. nghĩa là Đây là túi của tôi.", "Possessive determiners identify whose person or thing is meant. Das ist meine Tasche. means This is my bag.", "Đuôi thay đổi theo giống, số và cách của danh từ đi sau.", "The ending changes with the gender, number and case of the following noun."),
        (16, "predicate-adjectives", "Prädikative Adjektive", "Subjekt + sein + Adjektiv", "Tính từ sau sein", "Predicate adjectives", "Tính từ dùng sau sein không nhận đuôi biến cách. Die Wohnung ist klein. nghĩa là Căn hộ nhỏ.", "An adjective used after sein has no inflectional ending. Die Wohnung ist klein. means The apartment is small.", "Phân biệt với tính từ đứng trước danh từ, như eine kleine Wohnung.", "Distinguish this from an adjective before a noun, as in eine kleine Wohnung."),
        (17, "accusative", "Akkusativ", "Subjekt + Verb + Akkusativobjekt", "Tân ngữ Akkusativ", "Accusative objects", "Nhiều động từ như kaufen, sehen và haben có tân ngữ Akkusativ. Ich kaufe einen Apfel. nghĩa là Tôi mua một quả táo.", "Many verbs, including kaufen, sehen and haben, take an accusative object. Ich kaufe einen Apfel. means I am buying an apple.", "Mạo từ giống đực đổi der thành den, ein thành einen. die và das giữ nguyên ở Akkusativ.", "Masculine der becomes den and ein becomes einen. die and das stay unchanged in the accusative."),
        (18, "accusative-pronouns", "Personalpronomen im Akkusativ", "mich, dich, ihn, sie, es, uns, euch, sie, Sie", "Đại từ Akkusativ", "Accusative personal pronouns", "Thay danh từ làm tân ngữ Akkusativ bằng đại từ tương ứng. Ich sehe ihn. nghĩa là Tôi nhìn thấy anh ấy.", "Replace an accusative noun object with the matching pronoun. Ich sehe ihn. means I see him.", "Dạng đại từ được quyết định bởi chức năng trong câu, không chỉ bởi từ đứng gần nó.", "A pronoun's form follows its role in the sentence, rather than merely a nearby word."),
        (19, "dative", "Dativ", "Verb oder Präposition + Dativ", "Cách Dativ", "The dative case", "Một số động từ và giới từ yêu cầu Dativ. Ich helfe dem Kind. nghĩa là Tôi giúp đứa trẻ.", "Some verbs and prepositions require the dative. Ich helfe dem Kind. means I help the child.", "Mạo từ xác định Dativ là dem, der, dem, den theo giống đực, cái, trung và số nhiều. Danh từ số nhiều thường thêm -n nếu phù hợp.", "Dative definite articles are dem, der, dem and den for masculine, feminine, neuter and plural. Plural nouns commonly add -n where applicable."),
        (20, "dative-pronouns", "Personalpronomen im Dativ", "mir, dir, ihm, ihr, ihm, uns, euch, ihnen, Ihnen", "Đại từ Dativ", "Dative personal pronouns", "Dùng đại từ Dativ với động từ hoặc giới từ yêu cầu cách này. Kannst du mir helfen? nghĩa là Bạn giúp tôi được không?", "Use a dative pronoun where a verb or preposition requires it. Kannst du mir helfen? means Can you help me?", "Dạng lịch sự Ihnen được viết hoa.", "Formal Ihnen is capitalized."),
        (21, "dative-prepositions", "Präpositionen mit Dativ", "mit / nach / bei / seit / von / zu / aus + Dativ", "Giới từ đi với Dativ", "Dative prepositions", "Các giới từ mit, nach, bei, seit, von, zu và aus đi với Dativ. Ich fahre mit dem Bus. nghĩa là Tôi đi bằng xe buýt.", "The prepositions mit, nach, bei, seit, von, zu and aus take the dative. Ich fahre mit dem Bus. means I travel by bus.", "Học giới từ theo nghĩa và cụm từ thường dùng, như aus Vietnam hoặc zum Bahnhof.", "Learn prepositions with their meanings and common phrases, such as aus Vietnam or zum Bahnhof."),
        (22, "accusative-prepositions", "Präpositionen mit Akkusativ", "für / ohne / durch / gegen / um + Akkusativ", "Giới từ đi với Akkusativ", "Accusative prepositions", "Các giới từ für, ohne, durch, gegen và um đi với Akkusativ. Das Geschenk ist für meinen Bruder. nghĩa là Món quà dành cho anh/em trai tôi.", "The prepositions für, ohne, durch, gegen and um take the accusative. Das Geschenk ist für meinen Bruder. means The gift is for my brother.", "Phân biệt um trong giờ giấc với các cách dùng khác của cùng giới từ.", "Distinguish the time use of um from its other uses."),
        (23, "local-in-an-auf", "Ortsangaben mit Wechselpräpositionen", "wo + Dativ; wohin + Akkusativ", "Vị trí và đích đến", "Location and destination", "Với giới từ hai cách như in, an và auf, dùng Dativ cho vị trí và Akkusativ cho đích đến được xác lập. Ich bin in der Schule. và Ich gehe in die Schule. diễn đạt ở trường và đi vào/đến trường.", "With two-way prepositions such as in, an and auf, use dative for location and accusative for an expressed destination. Compare Ich bin in der Schule. with Ich gehe in die Schule.", "Có chuyển động chưa đủ để chọn Akkusativ. Cần xem giới từ diễn đạt vị trí hay đích đến.", "Movement alone does not determine the accusative. Check whether the preposition describes location or a destination."),
        (24, "time-prepositions", "Zeitangaben", "am + Tag; um + Uhrzeit; im + Monat", "Giới từ thời gian", "Time prepositions", "Dùng am với ngày, um với giờ và im với tháng hoặc mùa. Am Montag lerne ich. nghĩa là Tôi học vào thứ hai.", "Use am with days, um with clock times and im with months or seasons. Am Montag lerne ich. means I study on Monday.", "am là an dem và im là in dem trong các cách dùng tương ứng.", "am contracts an dem and im contracts in dem in the corresponding expressions."),
        (25, "clock-time", "Uhrzeiten", "Es ist ... Uhr.", "Nói giờ", "Telling the time", "Có thể nói giờ chính thức bằng số giờ rồi Uhr và số phút. Es ist acht Uhr dreißig. nghĩa là Bây giờ là tám giờ ba mươi.", "Formal clock time can use the hour, Uhr and the minutes. Es ist acht Uhr dreißig. means It is eight thirty.", "Trong cách nói thông thường, halb neun là tám giờ rưỡi, hướng tới giờ thứ chín.", "In everyday speech, halb neun means half past eight, approaching the ninth hour."),
        (26, "numbers", "Zahlenbildung", "Einheit + und + Zehner", "Số đếm", "Forming numbers", "Từ 21 đến 99, đọc hàng đơn vị trước hàng chục, nối bằng und. einundzwanzig là 21.", "For 21 to 99, the unit precedes the tens and is joined with und. einundzwanzig is 21.", "Có dạng đặc biệt như sechzehn, siebzehn, dreißig và sechzig.", "Special forms include sechzehn, siebzehn, dreißig and sechzig."),
        (27, "modal-can", "Modalverb können", "Subjekt + können + ... + Infinitiv", "Khả năng với können", "Ability with können", "Động từ tình thái đã chia đứng ở vị trí hai, động từ chính nguyên mẫu ở cuối. Ich kann Deutsch sprechen. nghĩa là Tôi có thể nói tiếng Đức.", "The conjugated modal occupies second position and the main infinitive goes at the end. Ich kann Deutsch sprechen. means I can speak German.", "Các dạng hiện tại là kann, kannst, kann, können, könnt, können.", "The present forms are kann, kannst, kann, können, könnt and können."),
        (28, "modal-must", "Modalverb müssen", "Subjekt + müssen + ... + Infinitiv", "Nghĩa vụ với müssen", "Obligation with müssen", "Dùng müssen để nói điều cần hoặc phải làm. Ich muss arbeiten. nghĩa là Tôi phải làm việc.", "Use müssen for necessity or obligation. Ich muss arbeiten. means I have to work.", "nicht müssen nghĩa là không cần phải, thường không có nghĩa bị cấm.", "nicht müssen means not having to do something, generally not a prohibition."),
        (29, "modal-permission", "Modalverb dürfen", "Subjekt + dürfen + ... + Infinitiv", "Xin phép và điều cấm", "Permission with dürfen", "Dùng dürfen để nói được phép. Darf ich hier sitzen? nghĩa là Tôi ngồi đây được không?", "Use dürfen for permission. Darf ich hier sitzen? means May I sit here?", "Du darfst hier nicht rauchen. diễn đạt Bạn không được hút thuốc ở đây.", "Du darfst hier nicht rauchen. means You are not allowed to smoke here."),
        (30, "modal-want", "wollen und möchte", "ich will / ich möchte + ... + Infinitiv", "Mong muốn", "Wants and polite wishes", "wollen diễn đạt mong muốn hoặc ý định. möchte thường dùng lịch sự hơn khi đề nghị hoặc gọi món. Ich möchte einen Tee. nghĩa là Tôi muốn một cốc trà.", "wollen expresses a wish or intention. möchte is often more polite for requests or ordering. Ich möchte einen Tee. means I would like a tea.", "möchte là một dạng của mögen, không phải nguyên mẫu độc lập.", "möchte is a form of mögen, not a separate infinitive."),
        (31, "separable-verbs", "Trennbare Verben", "Präfix + Stamm; im Hauptsatz Präfix am Ende", "Động từ tách tiền tố", "Separable verbs", "Trong câu chính hiện tại, tiền tố tách của động từ được đưa về cuối. Ich stehe um sieben Uhr auf. nghĩa là Tôi thức dậy lúc bảy giờ.", "In a present-tense main clause, a separable prefix moves to the end. Ich stehe um sieben Uhr auf. means I get up at seven.", "Nguyên mẫu là aufstehen. Khi đi cùng động từ tình thái, nguyên mẫu giữ nguyên ở cuối.", "The infinitive is aufstehen. With a modal verb the infinitive stays intact at the end."),
        (32, "imperative", "Imperativ", "Komm! Kommt! Kommen Sie!", "Câu mệnh lệnh và yêu cầu", "Imperatives and requests", "Chọn dạng yêu cầu theo du, ihr hoặc Sie. Kommen Sie bitte! nghĩa là Xin ông/bà hãy đến.", "Choose the imperative for du, ihr or Sie. Kommen Sie bitte! means Please come, in formal address.", "Dạng Sie giữ đại từ sau động từ. bitte giúp lời yêu cầu lịch sự hơn nhưng ngữ cảnh vẫn quan trọng.", "The Sie form retains the pronoun after the verb. bitte softens a request, while context still matters."),
        (33, "word-order-time", "Zeitangaben im Satz", "Zeitangabe im Vorfeld + Verb + Subjekt", "Đưa thời gian lên đầu câu", "Fronting a time expression", "Khi thời gian đứng đầu câu chính, chủ ngữ thường đứng sau động từ để giữ vị trí hai. Morgen arbeite ich. nghĩa là Ngày mai tôi làm việc.", "When a time expression begins the main clause, the subject commonly follows the verb to preserve verb-second order. Morgen arbeite ich. means I work tomorrow.", "Có thể nói Ich arbeite morgen. với cùng thông tin cơ bản nhưng trọng tâm khác.", "Ich arbeite morgen. gives similar basic information with a different focus."),
        (34, "coordination", "und, oder, aber", "Hauptsatz + und/oder/aber + Hauptsatz", "Nối câu chính", "Coordinating clauses", "und, oder và aber nối các câu chính. Ich lerne Deutsch und meine Schwester lernt Englisch. nghĩa là Tôi học tiếng Đức và chị/em gái tôi học tiếng Anh.", "und, oder and aber connect main clauses. Ich lerne Deutsch und meine Schwester lernt Englisch. means I study German and my sister studies English.", "Các liên từ này không chiếm vị trí thành phần đầu của mệnh đề được nối.", "These conjunctions do not occupy the first constituent position of the connected clause."),
        (35, "because-weil", "Nebensatz mit weil", "weil + Subjekt + ... + finites Verb", "Lý do với weil", "Reasons with weil", "Trong mệnh đề phụ dùng weil, động từ đã chia đứng cuối. Ich lerne, weil ich Zeit habe. nghĩa là Tôi học vì tôi có thời gian.", "In a subordinate clause introduced by weil, the finite verb goes at the end. Ich lerne, weil ich Zeit habe. means I study because I have time.", "Dùng dấu phẩy để ngăn mệnh đề phụ với mệnh đề chính.", "Separate the subordinate and main clauses with a comma."),
        (36, "subordinate-dass", "Nebensatz mit dass", "dass + Subjekt + ... + finites Verb", "Mệnh đề với dass", "Clauses with dass", "Dùng dass để dẫn một nội dung phát biểu hoặc suy nghĩ. Ich weiß, dass du hier wohnst. nghĩa là Tôi biết bạn sống ở đây.", "Use dass to introduce the content of a statement or thought. Ich weiß, dass du hier wohnst. means I know that you live here.", "Phân biệt liên từ dass với mạo từ hoặc đại từ das.", "Distinguish the conjunction dass from the article or pronoun das."),
        (37, "perfekt-haben", "Perfekt mit haben", "haben + ... + Partizip II", "Quá khứ Perfekt với haben", "The perfect with haben", "Nhiều động từ dùng haben và phân từ hai để kể việc đã xảy ra. Ich habe Deutsch gelernt. nghĩa là Tôi đã học tiếng Đức.", "Many verbs use haben and a past participle to report past events. Ich habe Deutsch gelernt. means I learned German.", "Trợ động từ chia theo chủ ngữ; phân từ thường ở cuối câu chính.", "The auxiliary agrees with the subject; the participle usually ends the main clause."),
        (38, "perfekt-sein", "Perfekt mit sein", "sein + ... + Partizip II", "Quá khứ Perfekt với sein", "The perfect with sein", "Một nhóm động từ, thường chỉ đổi vị trí hoặc trạng thái không có tân ngữ Akkusativ, dùng sein. Ich bin nach Hause gegangen. nghĩa là Tôi đã về nhà.", "A group of verbs, often intransitive changes of place or state, uses sein. Ich bin nach Hause gegangen. means I went home.", "Học trợ động từ cùng động từ. Không phải mọi động từ có chuyển động đều luôn dùng sein.", "Learn the auxiliary with the verb. Not every verb involving movement always uses sein."),
        (39, "past-participles", "Partizip II", "ge- + Stamm + -t / gelernte unregelmäßige Form", "Phân từ hai", "Past participles", "Động từ thường thường có ge- và -t, như gelernt. Động từ mạnh có dạng cần học riêng, như gesehen và geschrieben.", "Regular verbs commonly form the participle with ge- and -t, as in gelernt. Strong verbs have forms to learn individually, such as gesehen and geschrieben.", "Động từ tận cùng -ieren thường không thêm ge-, như studiert. Tiền tố tách và không tách cũng ảnh hưởng cách tạo.", "Verbs ending in -ieren generally omit ge-, as in studiert. Separable and inseparable prefixes also affect formation."),
        (40, "past-sein-haben", "Präteritum von sein und haben", "war / hatte", "Quá khứ của sein và haben", "Past forms of sein and haben", "war và hatte thường dùng để kể trạng thái hoặc việc có trong quá khứ. Ich war müde. nghĩa là Tôi đã mệt.", "war and hatte commonly describe past states or possession. Ich war müde. means I was tired.", "Các dạng cần chia theo chủ ngữ, như du warst và wir hatten.", "Inflect these forms for the subject, as in du warst and wir hatten."),
        (41, "future-present", "Zukunft mit Präsens", "Präsens + Zeitangabe", "Diễn đạt tương lai bằng hiện tại", "Future meaning with the present", "Có thể dùng hiện tại cùng thời gian tương lai để nói kế hoạch. Morgen fahre ich nach Berlin. nghĩa là Ngày mai tôi đi Berlin.", "The present tense with a future time expression can describe a plan. Morgen fahre ich nach Berlin. means I am going to Berlin tomorrow.", "Thời gian hoặc ngữ cảnh giúp xác định nghĩa tương lai.", "The time expression or context establishes the future meaning."),
        (42, "comparative", "Komparativ", "Adjektiv + -er; ... als ...", "So sánh hơn", "Comparatives", "Nhiều tính từ thêm -er ở so sánh hơn. Dieses Buch ist billiger als das andere. nghĩa là Quyển sách này rẻ hơn quyển kia.", "Many adjectives add -er for the comparative. Dieses Buch ist billiger als das andere. means This book is cheaper than the other one.", "Có biến âm và dạng bất quy tắc, như groß → größer và gut → besser.", "Some forms add an umlaut or are irregular, as in groß → größer and gut → besser."),
        (43, "superlative", "Superlativ", "am + Adjektiv + -sten/-esten", "So sánh nhất", "Superlatives", "Dạng trạng ngữ hoặc vị ngữ thường dùng am và -sten hoặc -esten. Dieses Zimmer ist am kleinsten. nghĩa là Phòng này nhỏ nhất.", "Adverbial or predicative superlatives commonly use am with -sten or -esten. Dieses Zimmer ist am kleinsten. means This room is the smallest.", "gut có dạng am besten. Dạng đứng trước danh từ còn nhận đuôi theo ngữ pháp của cụm danh từ.", "gut has am besten. A superlative before a noun also takes the appropriate noun-phrase ending."),
        (44, "adjectives-before-nouns", "Adjektive vor Nomen", "Artikel + Adjektivendung + Nomen", "Tính từ đứng trước danh từ", "Adjectives before nouns", "Tính từ trước danh từ nhận đuôi theo mạo từ, giống, số và cách. ein kleines Zimmer nghĩa là một căn phòng nhỏ.", "An adjective before a noun takes an ending based on the determiner, gender, number and case. ein kleines Zimmer means a small room.", "Học các mẫu như der kleine Tisch, ein kleiner Tisch và mit einem kleinen Tisch.", "Learn patterns such as der kleine Tisch, ein kleiner Tisch and mit einem kleinen Tisch."),
        (45, "demonstratives", "Demonstrativartikel", "dieser / diese / dieses + Nomen", "Từ chỉ định", "Demonstrative determiners", "dieser, diese và dieses giúp chỉ rõ đối tượng. Dieses Buch ist neu. nghĩa là Quyển sách này mới.", "dieser, diese and dieses identify a particular referent. Dieses Buch ist neu. means This book is new.", "Đuôi thay đổi theo giống, số và cách, tương tự nhóm mạo từ xác định.", "The endings change with gender, number and case, similarly to definite determiners."),
        (46, "quantity-words", "Mengenangaben", "viel / viele; wenig / wenige", "Từ chỉ lượng", "Quantity expressions", "viel thường dùng với lượng không đếm được, viele với danh từ đếm được số nhiều. viel Wasser và viele Bücher nghĩa là nhiều nước và nhiều sách.", "viel commonly describes an uncountable amount and viele countable plural items. Compare viel Wasser and viele Bücher.", "Các từ này cũng thay đổi theo cấu trúc và chức năng. Ví dụ này giới thiệu dạng cơ bản.", "Their forms also depend on structure and grammatical role. These examples introduce the basic pattern."),
        (47, "likes-gern", "Vorlieben mit gern", "Subjekt + Verb + gern", "Thích làm gì với gern", "Liking activities with gern", "Đặt gern trong câu để diễn đạt thích thực hiện hành động. Ich lese gern. nghĩa là Tôi thích đọc sách.", "Use gern to express enjoying an activity. Ich lese gern. means I like reading.", "So sánh mức thích bằng lieber và am liebsten.", "Compare preferences with lieber and am liebsten."),
        (48, "polite-requests", "Höfliche Bitten", "Könnten Sie bitte ...? / Ich hätte gern ...", "Nhờ và yêu cầu lịch sự", "Polite requests", "Könnten Sie bitte giúp lời nhờ mềm hơn. Könnten Sie bitte langsam sprechen? nghĩa là Ông/bà có thể nói chậm được không?", "Könnten Sie bitte softens a request. Könnten Sie bitte langsam sprechen? means Could you please speak slowly?", "Ich hätte gern thường dùng khi gọi món hoặc yêu cầu một thứ, như Ich hätte gern einen Kaffee.", "Ich hätte gern is common for ordering or requesting an item, as in Ich hätte gern einen Kaffee."),
        (49, "existence-es-gibt", "es gibt", "es gibt + Akkusativ", "Có một thứ gì ở đâu", "es gibt for existence", "Dùng es gibt để thông báo có hoặc tồn tại một thứ gì. Hier gibt es einen Bahnhof. nghĩa là Ở đây có một nhà ga.", "Use es gibt to state that something exists or is available. Hier gibt es einen Bahnhof. means There is a station here.", "Danh từ sau es gibt ở Akkusativ, kể cả khi động từ vẫn là gibt.", "The noun after es gibt is accusative, while the verb remains gibt."),
    ];

    public static readonly GrammarPoint[] PointRows = Points.Select(point => GrammarPoint.Create(
        SeedBase + 2200 + point.Key, SeedBase, point.Code, point.NativeName, point.Pattern, true, point.Key,
        FoundationSeedData.PublishedAt)).ToArray();

    public static readonly GrammarPointTranslation[] TranslationRows = Points.SelectMany(point => new[]
    {
        GrammarPointTranslation.Create(SeedBase + 2300 + point.Key * 2, SeedBase + 2200 + point.Key,
            "vi", point.VietnameseName, point.VietnameseExplanation, point.VietnameseNote, FoundationSeedData.PublishedAt),
        GrammarPointTranslation.Create(SeedBase + 2301 + point.Key * 2, SeedBase + 2200 + point.Key,
            "en", point.EnglishName, point.EnglishExplanation, point.EnglishNote, FoundationSeedData.PublishedAt)
    }).ToArray();
